namespace GodTreeXOwais.Runtime; [Flags] public enum Capability{None=0,ReadFiles=1,WriteFiles=2,Process=4,Network=8,Git=16} public sealed class PermissionBroker{readonly Dictionary<string,Capability> grants=new(StringComparer.OrdinalIgnoreCase){{"git",Capability.ReadFiles|Capability.WriteFiles|Capability.Process|Capability.Git},{"dotnet",Capability.ReadFiles|Capability.WriteFiles|Capability.Process},{"node",Capability.ReadFiles|Capability.WriteFiles|Capability.Process},{"npm",Capability.ReadFiles|Capability.WriteFiles|Capability.Process|Capability.Network},{"python",Capability.ReadFiles|Capability.WriteFiles|Capability.Process}};public void Demand(string tool,Capability required){if(!grants.TryGetValue(tool,out var got)||(got&required)!=required)throw new UnauthorizedAccessException($"Tool {tool} lacks {required}.");}}